events.command:
/bin/bash -lc "gzip -dc vcf.infer.ancestry.q1.vcf.gz | awk -F'\\t' '
"'!/''^#/ && length($4)==1 && length($5)==1 {
 n++;
 for(i=10;i<=13;i++){split($i,a,":"); gt=substr(a[1],1,1)+substr(a[1],3,1); dose[i-9]=gt; alt[i-9]+=gt; if(gt==1) het[i-9]++; if(gt==2) hom[i-9]++}
 sum=0; for(s=1;s<=4;s++)sum+=dose[s]; if(sum==1)for(s=1;s<=4;s++)if(dose[s]==1)singleton[s]++;
 if(sum==2)for(s=1;s<=4;s++)if(dose[s]==2)privatehom[s]++;
}
END{print "biallelic SNP",n; for(s=1;s<=4;s++) print s,"alt",alt[s],"het",het[s],"homalt",hom[s],"singleton",singleton[s],"privatehom",privatehom[s]}'"'"
